INSERT INTO artikel (judul, slug, kategori, konten, penulis, status) VALUES
('Apa Itu Teknologi Informasi dan Mengapa Penting?', 'apa-itu-teknologi-informasi', 'Konsep Teknologi Informasi', '<p>Teknologi Informasi (TI) adalah penggunaan komputer, perangkat lunak, jaringan, dan infrastruktur terkait untuk menciptakan, memproses, menyimpan, dan mendistribusikan semua bentuk data elektronik.</p><p>Di era digital saat ini, TI menjadi tulang punggung hampir semua sektor industri, mulai dari perbankan, kesehatan, pendidikan, hingga pemerintahan. Perusahaan yang mampu memanfaatkan teknologi informasi dengan baik akan memiliki keunggulan kompetitif yang signifikan.</p><h4>Manfaat Utama Teknologi Informasi</h4><ul><li>Meningkatkan efisiensi operasional</li><li>Mempercepat pengambilan keputusan berbasis data</li><li>Memperluas jangkauan pasar</li><li>Mengotomatisasi proses bisnis yang berulang</li><li>Meningkatkan kepuasan pelanggan</li></ul>', 'Agus Rifani', 'publish'),

('Panduan Lengkap Web Development untuk Pemula', 'panduan-web-development-pemula', 'Web Development', '<p>Web development adalah proses membangun dan memelihara website. Ini mencakup segala hal mulai dari membuat halaman web sederhana hingga aplikasi web yang kompleks, layanan jejaring sosial, dan bisnis online.</p><p>Untuk menjadi web developer yang handal, Anda perlu menguasai beberapa teknologi fundamental.</p><h4>Teknologi Dasar Web Development</h4><ul><li><strong>HTML</strong> - Struktur halaman web</li><li><strong>CSS</strong> - Tampilan dan gaya</li><li><strong>JavaScript</strong> - Interaktivitas</li><li><strong>PHP/Python/Node.js</strong> - Backend server</li><li><strong>MySQL/PostgreSQL</strong> - Database</li></ul>', 'Tim Agus Tech', 'publish'),

('Membangun Sistem Informasi yang Efektif', 'membangun-sistem-informasi-efektif', 'Sistem Informasi', '<p>Sistem Informasi (SI) adalah kombinasi teknologi informasi dan aktivitas manusia yang menggunakan teknologi tersebut untuk mendukung operasi dan manajemen.</p><p>Sistem informasi yang efektif dapat membantu organisasi dalam mencapai tujuan bisnis mereka dengan lebih efisien.</p><h4>Komponen Sistem Informasi</h4><ul><li>Hardware (Perangkat Keras)</li><li>Software (Perangkat Lunak)</li><li>Data (Basis Data)</li><li>Prosedur dan Kebijakan</li><li>Sumber Daya Manusia</li></ul>', 'Agus Rifani', 'publish'),

('Pentingnya Keamanan Website di Era Digital', 'pentingnya-keamanan-website', 'Keamanan Website', '<p>Keamanan website adalah praktik melindungi website dari ancaman siber yang dapat membahayakan data, reputasi, dan kelangsungan bisnis Anda.</p><p>Serangan siber semakin canggih dan sering. Setiap hari, ribuan website menjadi korban hacking, malware, dan berbagai ancaman digital lainnya.</p><h4>Ancaman Keamanan Website yang Umum</h4><ul><li>SQL Injection</li><li>Cross-Site Scripting (XSS)</li><li>DDoS Attack</li><li>Brute Force Login</li><li>Malware & Ransomware</li></ul><h4>Cara Melindungi Website Anda</h4><ul><li>Gunakan HTTPS/SSL Certificate</li><li>Update CMS dan plugin secara rutin</li><li>Gunakan password yang kuat</li><li>Backup data secara berkala</li><li>Pasang firewall aplikasi web (WAF)</li></ul>', 'Tim Security', 'publish');
